package com.lolfm.simulator;
import com.lolfm.domain.*;import java.util.*;
public final class ProgressionDiagnostics{
 enum Mode{LEGACY_OFF,STATE_ONLY,POWER_ON}
 public static void main(String[]args){System.out.println("PROGRESSION_DIAGNOSTICS constantsTuned=false randomConsumption=0 structured=true");for(Scenario s:scenarios()){run(s,1000);if(!s.key.equals("A")&&!s.key.equals("G"))run(s.mirror(),500);}focused();}
 private static void run(Scenario scenario,int seeds){for(Mode mode:Mode.values()){Aggregate a=new Aggregate(scenario.key+(scenario.mirrored?"_MIRROR":""),mode);for(int seed=1;seed<=seeds;seed++){MatchSimulator.SimulationResult r=sim(mode,true).simulateWithDiagnostics(scenario.team(TeamSide.BLUE),scenario.team(TeamSide.RED),seed);a.add(r);}a.print(seeds);}}
 private static MatchSimulator sim(Mode m,boolean diagnostics){SimulationOptions o=SimulationOptions.productionDefaults().withDiagnosticsEnabled(diagnostics);if(m==Mode.LEGACY_OFF)o=o.withProgressionEnabled(false);else if(m==Mode.STATE_ONLY)o=o.withProgressionPowerEnabled(false);return new MatchSimulator(new TeamfightResolver(),new EndGameEvaluator(),new SnapshotFactory(),new ObjectiveResolver(),new PostFightResolver(),new ObjectiveAttemptResolver(),new StructureResolver(),new PushResolver(),o);}
 private static final class Aggregate{final String key;final Mode mode;long winsB,winsR,duration,timeouts,supportCs,totalBlueXp,totalRedXp,totalBlueGold,totalRedGold,levelEvents,stageEvents;final EnumMap<ExperienceSource,Long>xp=new EnumMap<>(ExperienceSource.class);final EnumMap<Position,Double>levels=new EnumMap<>(Position.class),powers=new EnumMap<>(Position.class);long players,duplicateXp,duplicateLevel,duplicateStage,rollback,over18,offMutation,powerOffError,championError,positionError,levelSpikeError,deadBlocked,activityBlocked,recoveryBlocked,shared,adcSolo,supportSolo,absent,jungleTicks;final EnumMap<ProgressionCombatContext,Double>edges=new EnumMap<>(ProgressionCombatContext.class),contrib=new EnumMap<>(ProgressionCombatContext.class);Aggregate(String k,Mode m){key=k;mode=m;for(var x:ExperienceSource.values())xp.put(x,0L);for(var x:Position.values()){levels.put(x,0d);powers.put(x,0d);}for(var x:ProgressionCombatContext.values()){edges.put(x,0d);contrib.put(x,0d);}}
 void add(MatchSimulator.SimulationResult r){MatchTimeline t=r.timeline();duration+=t.getDurationSeconds();if(t.getWinner()==null)timeouts++;else if(t.getWinner().startsWith("BLUE"))winsB++;else winsR++;var st=r.progressionExecutionStats();st.experienceBySource().forEach((k,v)->xp.merge(k,(long)v,Long::sum));duplicateXp+=st.duplicateXpReward();duplicateLevel+=st.duplicateLevelEvent();duplicateStage+=st.duplicateItemEvent();rollback+=st.levelRollback()+st.itemRollback();over18+=st.levelOver18();offMutation+=st.featureOffMutation();powerOffError+=st.powerOffContributionError();championError+=st.championMultiplierError()+st.championSpikeError();positionError+=st.positionMultiplierError();levelSpikeError+=st.levelSpikeBonusError();deadBlocked+=st.deadEconomyXpBlocked();activityBlocked+=st.activityEconomyXpBlocked();recoveryBlocked+=st.farmRecoveryXpBlocked();shared+=st.botSharedTicks();adcSolo+=st.botAdcSoloTicks();supportSolo+=st.botSupportSoloTicks();absent+=st.botBothAbsentTicks();jungleTicks+=st.jungleEconomyXpTicks();st.progressionEdgeByContext().forEach((k,v)->edges.merge(k,v,Double::sum));st.contributionByContext().forEach((k,v)->contrib.merge(k,v,Double::sum));for(MatchEvent e:t.getEvents())if(e.getProgressionEvent()!=null){if(e.getProgressionEvent().type()==ProgressionEventType.LEVEL_UP)levelEvents++;else stageEvents++;}MatchSnapshot end=t.getSnapshots().getLast();for(PlayerSnapshot p:end.getPlayerSnapshots()){players++;levels.merge(p.getPosition(),(double)p.getLevel(),Double::sum);powers.merge(p.getPosition(),p.getProgressionPower().totalPower(),Double::sum);supportCs+=p.getPosition()==Position.SUPPORT?p.getCs():0;if(p.getTeamSide()==TeamSide.BLUE){totalBlueXp+=p.getTotalExperience();totalBlueGold+=p.getProgressionEarnedGold();}else{totalRedXp+=p.getTotalExperience();totalRedGold+=p.getProgressionEarnedGold();}}}
 void print(int seeds){System.out.printf(Locale.ROOT,"REPORT key=%s mode=%s seeds=%d xp={source=%s,blue=%d,red=%d} bot={shared=%d,adcSolo=%d,supportSolo=%d,absent=%d,supportCs=%d} jungle={ticks=%d,activityBlock=%d,recoveryBlock=%d} growth={levels=%s,power=%s,levelEvents=%d,stageEvents=%d,gold=%d/%d} combat={edge=%s,contribution=%s} result={W=%d/%d,avg=%.1f,timeout=%d} integrity={dupXp=%d,dupLevel=%d,dupStage=%d,rollback=%d,over18=%d,offMutation=%d,powerOff=%d,champion=%d,position=%d,levelSpike=%d,deadBlocked=%d}%n",key,mode,seeds,xp,totalBlueXp,totalRedXp,shared,adcSolo,supportSolo,absent,supportCs,jungleTicks,activityBlocked,recoveryBlocked,avg(levels,seeds*2),avg(powers,seeds*2),levelEvents,stageEvents,totalBlueGold,totalRedGold,edges,contrib,winsB,winsR,duration/(double)seeds,timeouts,duplicateXp,duplicateLevel,duplicateStage,rollback,over18,offMutation,powerOffError,championError,positionError,levelSpikeError,deadBlocked);}
 private Map<Position,Double>avg(Map<Position,Double>x,int teams){EnumMap<Position,Double>r=new EnumMap<>(Position.class);x.forEach((k,v)->r.put(k,v/teams));return r;}}
 private static void focused(){System.out.println("FOCUSED_PROGRESSION");GameState s=LateGameTestSupport.state();PlayerState top=s.getBlueTeamState().playerAt(Position.TOP);System.out.println("fresh level="+top.getProgressionState().getLevel()+" xp="+top.getProgressionState().getTotalExperience()+" stage="+top.getProgressionState().getItemStage());top.getProgressionState().awardExperience(ExperienceSource.LANE_ECONOMY,279,1);System.out.println("xp279 level="+top.getProgressionState().getLevel());top.getProgressionState().awardExperience(ExperienceSource.LANE_ECONOMY,1,2);System.out.println("xp280 level="+top.getProgressionState().getLevel());GameState bot=LateGameTestSupport.state();bot.advanceTimeSeconds(300);new ProgressionEconomyResolver().resolve(bot,300);System.out.println("botShared adc/sup="+bot.getBlueTeamState().playerAt(Position.ADC).getProgressionState().getTotalExperience()+"/"+bot.getBlueTeamState().playerAt(Position.SUPPORT).getProgressionState().getTotalExperience());GameState kill=LateGameTestSupport.state();new KillRewardResolver().award(300,kill.getBlueTeamState(),kill.getBlueTeamState().playerAt(Position.MID),kill.getRedTeamState(),kill.getRedTeamState().playerAt(Position.MID),List.of(kill.getBlueTeamState().playerAt(Position.JUNGLE),kill.getBlueTeamState().playerAt(Position.SUPPORT)),20,false,0,new ArrayList<>());System.out.println("killXp="+kill.getBlueTeamState().playerAt(Position.MID).getProgressionState().getTotalExperience()+" assists="+kill.getBlueTeamState().playerAt(Position.JUNGLE).getProgressionState().getTotalExperience()+"/"+kill.getBlueTeamState().playerAt(Position.SUPPORT).getProgressionState().getTotalExperience());var before=new SnapshotFactory().create(kill);kill.getBlueTeamState().playerAt(Position.TOP).getProgressionState().awardExperience(ExperienceSource.KILL,5000,400);System.out.println("snapshotImmutable="+(before.getPlayerSnapshots().stream().filter(p->p.getTeamSide()==TeamSide.BLUE&&p.getPosition()==Position.TOP).findFirst().orElseThrow().getLevel()==1));System.out.println("thresholds xp="+Arrays.toString(ProgressionRuleConfig.TOTAL_XP_BY_LEVEL)+" item=1200/3500/7000/10500/14000/17500");}
 private static List<Scenario>scenarios(){Profile eq=Profile.all(14,14,14,14);return List.of(new Scenario("A",eq,eq,false),new Scenario("B",Profile.all(14,14,18,14),Profile.all(14,14,10,14),false),new Scenario("C",Profile.farm(Position.MID,20),Profile.farm(Position.MID,8),false),new Scenario("D",Profile.farm(Position.ADC,20),Profile.farm(Position.ADC,8),false),new Scenario("E",Profile.agg(Position.JUNGLE,20),Profile.agg(Position.JUNGLE,8),false),new Scenario("F",Profile.all(18,18,14,18),Profile.all(10,10,14,10),false),new Scenario("G",eq,eq,false));}
 private record Scenario(String key,Profile blue,Profile red,boolean mirrored){Scenario mirror(){return new Scenario(key,red,blue,true);}Team team(TeamSide side){Profile p=side==TeamSide.BLUE?blue:red;String n=(side==TeamSide.BLUE?"BLUE":"RED")+"-"+key+(mirrored?"M":"");List<Player>x=new ArrayList<>();for(Position pos:Position.values()){int[]v=p.v.get(pos);x.add(new Player(n+"-"+pos,pos,new PlayerAttributes(v[0],v[1],v[2],v[3])));}return new Team(n,x);}}
 private static final class Profile{final EnumMap<Position,int[]>v=new EnumMap<>(Position.class);static Profile all(int m,int a,int f,int t){Profile p=new Profile();for(Position x:Position.values())p.v.put(x,new int[]{m,a,f,t});return p;}static Profile farm(Position pos,int f){Profile p=all(14,14,14,14);p.v.put(pos,new int[]{14,14,f,14});return p;}static Profile agg(Position pos,int a){Profile p=all(14,14,14,14);p.v.put(pos,new int[]{14,a,14,14});return p;}}
}
